from django.db.models import F
from django.http import JsonResponse
from django.shortcuts import get_object_or_404
from django.views.decorators.http import require_POST

from .models import Product


@require_POST
def order(request, product_id):
    updated = Product.objects.filter(pk=product_id, stock__gte=1).update(
        stock=F("stock") - 1
    )
    if not updated:
        get_object_or_404(Product, pk=product_id)
        return JsonResponse({"error": "out of stock"}, status=409)
    product = Product.objects.get(pk=product_id)
    return JsonResponse({"stock": product.stock})

from django.contrib.auth.decorators import login_required
from django.db import transaction
from django.http import JsonResponse
from django.shortcuts import get_object_or_404
from django.views.decorators.http import require_POST

from .models import Order, Product


@require_POST
@login_required
def order(request, product_id):
    with transaction.atomic():
        product = get_object_or_404(
            Product.objects.select_for_update(), pk=product_id
        )
        if Order.objects.filter(user=request.user, product=product).exists():
            return JsonResponse({"error": "already ordered"}, status=409)
        if product.stock < 1:
            return JsonResponse({"error": "out of stock"}, status=409)
        product.stock -= 1
        product.save(update_fields=["stock"])
        Order.objects.create(user=request.user, product=product)
    return JsonResponse({"stock": product.stock})
